 function build(preserve=true){if(preserve)captureDrafts();hitCleanup?.();core?.destroy();const proto=getThermalProtocol(activity,locale);host.innerHTML=renderPilotShell({activity,locale,state});q('#l3Notebook').innerHTML=renderNotebook(session,locale);const quick=document.createElement('section');quick.className='l3-quick-reading';const writing=q('#l3Notebook .l3-writing');while(writing.firstChild)quick.append(writing.firstChild);writing.remove();q('#l3Readings').after(quick);const masses=document.createElement('div');masses.className='l3-setup';masses.innerHTML=`<label>${t('Khối lượng nước em cân (g)','Your weighed water mass (g)')}<input type="number" min="0" max="2000" step=".1" data-l3-mass="water" autocomplete="off"></label><label>${t(activity==='ice'?'Khối lượng đá em cân (g)':'Khối lượng vật em cân (g)',activity==='ice'?'Your weighed ice mass (g)':'Your weighed solid mass (g)')}<input type="number" min="0" max="2000" step=".1" data-l3-mass="sample" autocomplete="off"></label>`;quick.append(masses);q('#l3Protocol').innerHTML=`<label>${t('Chế độ học','Investigation mode')}<select data-l3-field="mode">${proto.modes.map(m=>`<option value="${m.id}" ${session.mode===m.id?'selected':''}>${esc(m.label)}</option>`).join('')}</select></label><details id="l3Guided" ${session.mode==='guided'?'open':''}><summary>${t('Gợi ý điều tra','Investigation prompts')}</summary><ol>${proto.guidedPrompts.map(p=>`<li>${esc(p.prompt)}</li>`).join('')}</ol></details><details><summary>${t('Bằng chứng đã ghi','Recorded evidence')}</summary><ul id="l3Evidence"></ul><p>${esc(proto.teacherReview)}</p></details>`;
  const time=document.createElement('div');time.className='l3-time-tools';time.innerHTML=`<button data-l3-action="step">${t('Tiến 1 s','Step 1 s')}</button><label>${t('Tốc độ thời gian','Time rate')}<select data-l3-field="speed"><option value="1">1×</option><option value="5">5×</option><option value="20">20×</option></select></label>`;q('.l3-stage-column').append(time);const pan=document.createElement('button');pan.dataset.l3Action='empty-pan';pan.textContent=t('Đặt đĩa cân rỗng','Load empty weighing pan');q('.l3-context-actions').append(pan);
  for(const input of host.querySelectorAll('[data-l3-config]')){const name=input.dataset.l3Config;input.value=String(name==='sampleMassKg'?state.config[activity==='ice'?'iceMassKg':'solidMassKg']:state.config[name]);}
  for(const n of host.querySelectorAll('[data-l3-mass]'))if(session.drafts?.masses?.[n.dataset.l3Mass]!==undefined)n.value=session.drafts.masses[n.dataset.l3Mass];if(session.drafts?.temperature!==undefined)q('#l3StudentTemperature').value=session.drafts.temperature;for(const n of host.querySelectorAll('[data-l3-calc]'))if(session.drafts?.calculation?.[n.dataset.l3Calc]!==undefined)n.value=session.drafts.calculation[n.dataset.l3Calc];for(const n of host.querySelectorAll('[data-l3-config]'))if(session.drafts?.config?.[n.dataset.l3Config]!==undefined)n.value=session.drafts.config[n.dataset.l3Config];
  core=installInteractionCore(q('#l3Stage'),{positions,onMove:move,onDrop:drop,onActivate:drop,onRotate:rotate,onStir:stir,onCamera:box=>{cameraBox=box;zoom=800/box.width;saveSoon();},getRotation:()=>angle,getSelected:()=>selected,getStirCenter:()=>({x:410,y:(waterSurfaceY(state)+342)/2}),canStart:canMove,onCancel:()=>{angle=0;running=false;message(t('Đã dừng thao tác; giữ những thay đổi đã xảy ra.','Interaction stopped; previous physical changes are retained.'));refresh();}});if(cameraBox)q('#l3Stage').setAttribute('viewBox',`${cameraBox.x} ${cameraBox.y} ${cameraBox.width} ${cameraBox.height}`);hitCleanup=installThermalHitTargets(q('#l3Stage'));drawNotebook();refresh();q('h1')?.focus({preventScroll:true});
 }
 function animate(now){if(disposed)return;frame=requestAnimationFrame(animate);const dt=last?Math.min(.1,(now-last)/1000):0;last=now;if(running&&!document.hidden){accumulator+=dt*speed;if(accumulator>=.05){const elapsed=Math.min(2,accumulator);accumulator-=elapsed;try{stepTime(elapsed);}catch(error){running=false;message(t('Mô hình đã tạm dừng: ','Model paused: ')+error.message);}}}else accumulator=0;if(now-lastSaveReal>1000){lastSaveReal=now;saveNow();}}
