 return {destroy(){if(disposed)return;running=false;saveNow();disposed=true;clearTimeout(saveTimer);cancelAnimationFrame(frame);hitCleanup?.();core?.destroy();offLocale();host.removeEventListener('click',click);host.removeEventListener('input',input);host.removeEventListener('change',change);host.removeEventListener('keydown',stopKeys);document.removeEventListener('visibilitychange',hidden);window.removeEventListener('pagehide',pageHide);},getContext(){const result={id:'calorimetry-l3-'+activity,catalogId:'calorimetry',title:getThermalProtocol(activity,getLocale()).title,conditions:'Two-node insulated calorimeter; manual readings, finite instrument response. No automatic equilibrium answer or teacher sign-off.',parameters:[],columns:['trial','t (s)','student T (K)','valid'],measurements:session.trials.flatMap(t=>t.readings.map(r=>[t.trialId,r.simTimeS,r.studentValue,r.valid])).slice(-12)};return result;},getSession:()=>clone(backup())};
